#[cfg(test)]
mod p4_fragment_arguments {
    use super::fragments;
    use std::rc::Rc;
    use crate::util::names::Names;
    use javac_strings::JavaString;

    #[test]
    fn undecl_type_var_takes_the_name_argument() {
        let names = Names::new(false);
        let name = names.from_string(&JavaString::from("T"));
        let info = fragments::undecl_type_var(name);
        assert_eq!(info.info().key(), "compiler.misc.undecl.type.var");
        assert_eq!(info.info().args.len(), 1);
    }

    #[test]
    fn undecl_type_var_message_matches_javac_oracle() {
        // Oracle (JDK 17, Locale.ENGLISH, JCDiagnostic.Factory.fragment):
        // "undeclared type variable: T"
        use crate::util::jc_diagnostic::Factory;
        use crate::util::javac_messages::{JavacMessages, DEFAULT_BUNDLE_NAME};
        let messages = Rc::new(JavacMessages::new(DEFAULT_BUNDLE_NAME));
        let factory = Factory::new(messages, "compiler");
        let names = Names::new(false);
        let name = names.from_string(&JavaString::from("T"));
        let diag = factory.fragment(crate::util::jc_diagnostic::Fragment::from(
            fragments::undecl_type_var(name),
        ));
        assert_eq!(
            diag.get_message(None).to_string(),
            "undeclared type variable: T"
        );
    }

    #[test]
    fn wrong_version_message_matches_javac_oracle() {
        // Oracle (JDK 17, Locale.ENGLISH, JCDiagnostic.Factory.fragment):
        // "class file has wrong version 63.0, should be 61.0"
        use crate::util::jc_diagnostic::Factory;
        use crate::util::javac_messages::{JavacMessages, DEFAULT_BUNDLE_NAME};
        let messages = Rc::new(JavacMessages::new(DEFAULT_BUNDLE_NAME));
        let factory = Factory::new(messages, "compiler");
        let diag = factory.fragment(crate::util::jc_diagnostic::Fragment::from(
            fragments::wrong_version(
                JavaString::from("63"),
                JavaString::from("0"),
                JavaString::from("61"),
                JavaString::from("0"),
            ),
        ));
        assert_eq!(
            diag.get_message(None).to_string(),
            "class file has wrong version 63.0, should be 61.0"
        );
    }

    #[test]
    fn bad_constant_messages_match_javac_oracle() {
        // Oracle (JDK 17, Locale.ENGLISH, JCDiagnostic.Factory.fragment):
        // bad.constant.value(Integer 5, VarSymbol v, "String")
        //   -> "bad constant value '5' for v, expected String"
        // bad.constant.range(Integer 5, VarSymbol v, int)
        //   -> "constant value '5' for v is outside the expected range for int"
        use crate::resources::diagnostic_contract::{SymbolArg, TypeArg};
        use crate::util::jc_diagnostic::{Factory, Fragment};
        use crate::util::javac_messages::{JavacMessages, DEFAULT_BUNDLE_NAME};
        let messages = Rc::new(JavacMessages::new(DEFAULT_BUNDLE_NAME));
        let factory = Factory::new(messages, "compiler");
        let value = factory.fragment(Fragment::from(fragments::bad_constant_value(
            JavaString::from("5"),
            SymbolArg::placeholder("v"),
            JavaString::from("String"),
        )));
        assert_eq!(
            value.get_message(None).to_string(),
            "bad constant value '5' for v, expected String"
        );
        let range = factory.fragment(Fragment::from(fragments::bad_constant_range(
            JavaString::from("5"),
            SymbolArg::placeholder("v"),
            TypeArg::placeholder("int"),
        )));
        assert_eq!(
            range.get_message(None).to_string(),
            "constant value '5' for v is outside the expected range for int"
        );
    }

    #[test]
    fn wrong_version_takes_four_arguments() {
        let info = fragments::wrong_version(
            JavaString::from("61"),
            JavaString::from("0"),
            JavaString::from("60"),
            JavaString::from("0"),
        );
        assert_eq!(info.info().key(), "compiler.misc.wrong.version");
        assert_eq!(info.info().args.len(), 4);
    }
}
